String raw = String.fromCharArray(new List<Integer>{8, 9, 10, 12, 13, 34, 39, 47, 92, 937, 55357, 56832});
System.assertEquals(raw, raw.escapeJava().unescapeJava());
System.assertEquals(raw, raw.escapeEcmaScript().unescapeEcmaScript());
String unicodeRaw = String.fromCharArray(new List<Integer>{8, 9, 10, 12, 13, 34, 39, 47, 937, 55357, 56832});
String expectedUnicodeEscaped = String.fromCharArray(new List<Integer>{92,117,48,48,48,56,92,117,48,48,48,57,92,117,48,48,48,65,92,117,48,48,48,67,92,117,48,48,48,68,34,39,47,92,117,48,51,65,57,92,117,68,56,51,68,92,117,68,69,48,48});
String unicodeEscaped = unicodeRaw.escapeUnicode();
System.assertEquals(expectedUnicodeEscaped, unicodeEscaped);
System.assertEquals(unicodeRaw, unicodeEscaped.unescapeUnicode());
System.assertEquals('/', '/'.escapeJava());
System.assertEquals('\/', '/'.escapeEcmaScript());

String face = String.fromCharArray(new List<Integer>{55357, 56832});
System.assertEquals(2, face.length());
System.assertEquals(128512, face.codePointAt(0));
System.assertEquals(128512, face.codePointBefore(2));
System.assertEquals(1, face.codePointCount(0, 2));
List<Integer> faceChars = face.getChars();
System.assertEquals(2, faceChars.size());
System.assertEquals(55357, faceChars.get(0));
System.assertEquals(56832, faceChars.get(1));

System.assertEquals('abc...', 'abcdefg'.abbreviate(6));
System.assertEquals('...lmnopq...', 'abcdefghijklmnopqrstuvwxyz'.abbreviate(12, 11));
System.assertEquals('abXXef', 'abcdef'.overlay('XX', 4, 2));
System.assertEquals('abcdefZZ', 'abcdef'.overlay('ZZ', 99, 100));
System.assertEquals('aZ 9ω', 'Az 9Ω'.swapCase());

